local _evyesz = 71
local _tukjbl = 196
local _vejdth = ""

local _pfnohj = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _qaimyt(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _ysohba(d)
	d = d:gsub("[^" .. _pfnohj .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_pfnohj:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _tpchvs = _ysohba(_vejdth)
local _nilerq = { _lniqsr, _evyesz, _tukjbl }
local _xdytuy = {}
for i = 1, #_tpchvs do
	_xdytuy[i] = string.char(_qaimyt(_tpchvs:byte(i), _nilerq[(i - 1) % 3 + 1]))
